#!/usr/bin/env python3
"""Print the row count and per-column min/max/mean of a CSV file."""

import argparse
import csv
import math
import sys
from dataclasses import dataclass


@dataclass
class ColumnStats:
    name: str
    count: int = 0
    total: float = 0.0
    minimum: float | None = None
    maximum: float | None = None
    numeric: bool = True

    def add(self, cell: str) -> None:
        cell = cell.strip()
        if not cell or not self.numeric:
            return
        try:
            value = float(cell)
        except ValueError:
            self.numeric = False
            return
        if not math.isfinite(value):
            self.numeric = False
            return
        self.count += 1
        self.total += value
        self.minimum = value if self.minimum is None else min(self.minimum, value)
        self.maximum = value if self.maximum is None else max(self.maximum, value)

    @property
    def mean(self) -> float | None:
        return self.total / self.count if self.count else None

    @property
    def has_stats(self) -> bool:
        return self.numeric and self.count > 0


def compute_stats(rows):
    """Return (row_count, [ColumnStats]) for an iterable of CSV rows.

    The first row is the header. A column is numeric only if every non-empty
    cell parses as a finite float; empty cells are ignored.
    """
    rows = iter(rows)
    header = next(rows, None)
    if header is None:
        return 0, []
    columns = [ColumnStats(name) for name in header]
    row_count = 0
    for row in rows:
        if not row:
            continue
        row_count += 1
        for column, cell in zip(columns, row):
            column.add(cell)
    return row_count, columns


def _fmt(value: float | None) -> str:
    return "-" if value is None else f"{value:.6g}"


def format_report(row_count: int, columns) -> str:
    lines = [f"rows: {row_count}"]
    if not columns:
        return "\n".join(lines)
    table = [("column", "min", "max", "mean")]
    for column in columns:
        if column.has_stats:
            table.append(
                (
                    column.name,
                    _fmt(column.minimum),
                    _fmt(column.maximum),
                    _fmt(column.mean),
                )
            )
        else:
            table.append((column.name, "-", "-", "-"))
    widths = [max(len(row[i]) for row in table) for i in range(4)]
    for row in table:
        lines.append("  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip())
    return "\n".join(lines)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", help="CSV file to summarize, or - for stdin")
    parser.add_argument("-d", "--delimiter", default=",", help="field delimiter (default: ,)")
    args = parser.parse_args(argv)

    try:
        if args.path == "-":
            row_count, columns = compute_stats(csv.reader(sys.stdin, delimiter=args.delimiter))
        else:
            with open(args.path, newline="", encoding="utf-8-sig") as handle:
                row_count, columns = compute_stats(csv.reader(handle, delimiter=args.delimiter))
    except (OSError, UnicodeDecodeError, csv.Error) as exc:
        print(f"csvstat: {exc}", file=sys.stderr)
        return 1

    print(format_report(row_count, columns))
    return 0


if __name__ == "__main__":
    sys.exit(main())
